#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Sets up the GitHub demo repo (in a free org, with a bot account owning the
# hub's token), points the VM's hub at it, and checks #28 end to end:
# INC-1042 opens a pull request, the token can't push to main or merge, a
# change merged on GitHub reaches the next task, and the demo resets.
# docs/deploying.md, section 3. Run from your laptop, in the team-workspace
# checkout, after deploy/vm-wizard.sh has built the VM:
#   bash deploy/demo-repo-wizard.sh
# The token goes from your hidden input into a shell variable, the VM's .env
# (through an SSH pipe) and the env of single commands: never argv, never a
# local file.

TOTAL_STAGES=14

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
WIZ_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/team-workspace-vm"
mkdir -p "$WIZ_DIR"
ENV_FILE="$WIZ_DIR/demo-repo.state"      # non-secret answers, for re-runs
VM_STATE="$WIZ_DIR/vm.state"             # written by deploy/vm-wizard.sh
FINDINGS="$WIZ_DIR/demo-repo-findings.md"
REMOTE_DIR=/opt/team-workspace
HUB_REPO=/var/lib/team-workspace/repo
VM_KEY="$HOME/.ssh/team-workspace-vultr"
SSH_OPTS=(-i "$VM_KEY" -o IdentitiesOnly=yes)
ASKPASS="$REPO/apps/hub/src/tasks/git-askpass.sh"
GITHUB_TOKEN=""
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"; GITHUB_TOKEN=""' EXIT

state_of() { grep -E "^$1=" "$VM_STATE" 2>/dev/null | tail -n1 | cut -d= -f2-; }
VM_IP=$(state_of VM_IP)
VM_USER=$(state_of VM_USER)
DOMAIN="$VM_IP.sslip.io"
BASE="https://$DOMAIN"

record() { printf -- '- %s\n' "$1" >> "$FINDINGS"; }
vm() { ssh "${SSH_OPTS[@]}" -o BatchMode=yes -o ConnectTimeout=10 "$VM_USER@$VM_IP" "$@"; }

check() { # check "name" <pass|fail> "detail"
  if [[ "$2" == pass ]]; then
    printf '  %s✓ PASS%s %s\n' "$GREEN" "$RESET" "$1"; record "Check PASS: $1${3:+ ($3)}"
  else
    printf '  %s✗ FAIL%s %s\n' "$RED" "$RESET" "$1"; record "Check FAIL: $1${3:+ ($3)}"
  fi
}

# Upserts KEY=<stdin> into the VM's .env as the hub user, keeping mode 600.
# Same helper as vm-wizard.sh: the script travels base64-encoded in the
# command, the value only on stdin.
UPSERT_B64=$(base64 -w0 <<'EOF'
set -eu
key=$1; f=/opt/team-workspace/.env
IFS= read -r v || true
tmp=$(mktemp); trap 'rm -f "$tmp"' EXIT
grep -v "^$key=" "$f" > "$tmp" || true
printf '%s=%s\n' "$key" "$v" >> "$tmp"
cat "$tmp" > "$f"
EOF
)
vm_env() {
  vm "sudo -u hub bash -c \"\$(echo $UPSERT_B64 | base64 -d)\" upsert $1"
  printf '  %s✓ set%s %s in the VM .env\n' "$GREEN" "$RESET" "$1"
}

# The API with the hub's token: the header goes to curl on stdin, never argv.
# Prints the HTTP status, the body lands in $WORK/body.
tok_api() { # tok_api METHOD PATH [json-body]
  local data=()
  [[ $# -ge 3 ]] && data=(--data "$3")
  printf 'Authorization: Bearer %s\n' "$GITHUB_TOKEN" | curl -sS -o "$WORK/body" -w '%{http_code}' \
    -X "$1" -H @- -H 'Accept: application/vnd.github+json' "${data[@]}" "https://api.github.com$2"
}

need_token() {
  [[ -n "$GITHUB_TOKEN" ]] && return 0
  say "Copy the hub's token (the bot's fine-grained token) from the password manager."
  read -rs -p "  Paste the token (hidden): " GITHUB_TOKEN || true
  printf '\n'
  # A hidden paste can carry bracketed-paste markers or stray whitespace.
  GITHUB_TOKEN=$(printf '%s' "$GITHUB_TOKEN" | sed $'s/\x1b\\[20[01]~//g' | tr -d '[:space:][:cntrl:]')
  [[ -n "$GITHUB_TOKEN" ]] || { warn "no token given"; return 1; }
}

# Waits for a task from the support view that started after $1 (epoch secs)
# and prints its id once it has a status in $2 (a jq array of statuses).
wait_task() {
  local since=$1 until=$2 id="" snap status
  for _ in $(seq 1 200); do
    if [[ -z "$id" ]]; then
      id=$(curl -fsS --max-time 10 "$BASE/api/tasks" 2>/dev/null | jq -r --argjson s "$since" \
        '[.[] | select(.input.incidentId == "INC-1042") | select((.createdAt | sub("\\.[0-9]+Z$"; "Z") | fromdateiso8601) >= $s)] | sort_by(.createdAt) | last | .id // empty' || true)
      [[ -n "$id" ]] && note "task $id" >&2
    else
      snap=$(curl -fsS --max-time 10 "$BASE/api/tasks/$id" 2>/dev/null || true)
      status=$(jq -r '.status // empty' <<<"$snap" 2>/dev/null || true)
      printf '\r  %sstatus: %-10s phase: %-10s%s' "$DIM" "${status:-?}" "$(jq -r '.phase // "-"' <<<"$snap" 2>/dev/null)" "$RESET" >&2
      if jq -e --arg s "$status" --argjson u "$until" '$u | index($s)' >/dev/null 2>&1 <<<'null'; then
        printf '\n' >&2; printf '%s' "$id"; return 0
      fi
    fi
    sleep 3
  done
  printf '\n' >&2
  return 1
}
DONE='["pr_opened","gave_up","flagged","error","proposed"]'

banner "Demo repo on GitHub, and the pull request check (#28)"
printf '\n## Demo repo run %s\n\n' "$(date -u +'%Y-%m-%d %H:%M UTC')" >> "$FINDINGS"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
missing=()
for c in gh git ssh curl jq base64; do command -v "$c" >/dev/null || missing+=("$c"); done
(( ${#missing[@]} )) && { warn "missing: ${missing[*]}"; exit 1; }
[[ -n "$VM_IP" && -n "$VM_USER" ]] || { warn "no VM in $VM_STATE: run deploy/vm-wizard.sh first"; exit 1; }
gh auth status >/dev/null 2>&1 || { warn "gh isn't logged in: run gh auth login (as you, the developer)"; exit 1; }
ME=$(gh api user -q .login)
say "gh is logged in as $ME. That's the developer: you'll own the org and merge."
if ! vm true 2>/dev/null; then
  warn "can't reach $VM_USER@$VM_IP. The key has a passphrase: start an agent and add it."
  note "fish: eval (ssh-agent -c); ssh-add $VM_KEY"
  exit 1
fi
say "The VM answers: $VM_USER@$VM_IP."
say ""
say "The demo repo lives in a free GitHub org you own. A bot account, a member"
say "of that org, owns the hub's token: you approve and merge its pull requests,"
say "and nobody can approve their own. (A fine-grained token can't reach a repo"
say "on a personal account where its owner is only a collaborator.)"
ask GH_ORG "Org name (new or existing, e.g. sandbugs-demo):"
ask DEMO_NAME "Repo name in it (e.g. shop):"
ask BOT "The bot's GitHub username:"
GITHUB_REPO="$GH_ORG/$DEMO_NAME"
[[ "$GITHUB_REPO" =~ ^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ && -n "$BOT" ]] || { warn "not a valid org/repo or bot: $GITHUB_REPO, $BOT"; exit 1; }
write_env GH_ORG "$GH_ORG"; write_env DEMO_NAME "$DEMO_NAME"; write_env BOT "$BOT"
record "Demo repo: $GITHUB_REPO, token owner: $BOT"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "The org and the bot"
if gh api "orgs/$GH_ORG" >/dev/null 2>&1; then
  say "The org $GH_ORG exists."
else
  say "Create the org, on the Free plan, owned by you ($ME):"
  open_url "https://github.com/account/organizations/new?plan=free"
  step "Organization name: $GH_ORG. Contact email: yours. Belongs to: My personal account."
  pause "Press Enter once the org exists"
  gh api "orgs/$GH_ORG" >/dev/null 2>&1 || { warn "can't see orgs/$GH_ORG with your gh login"; exit 1; }
fi
gh api -X PATCH "orgs/$GH_ORG" -f default_repository_permission=none >/dev/null \
  && say "Base permission for members: none (the bot gets the one repo only)."
if gh api "orgs/$GH_ORG/members/$BOT" >/dev/null 2>&1; then
  say "$BOT is already a member."
else
  if ! gh api "users/$BOT" >/dev/null 2>&1; then
    say "The bot account doesn't exist yet. Sign up in a private window, with an"
    say "address you control, and save its password and 2FA in the password manager."
    open_url "https://github.com/signup"
    pause "Press Enter once $BOT exists"
  fi
  if ! gh api -X PUT "orgs/$GH_ORG/memberships/$BOT" -f role=member >/dev/null 2>"$WORK/err"; then
    warn "couldn't invite $BOT: $(head -c 200 "$WORK/err")"
    say "Inviting needs the admin:org scope on your gh login. Add it, re-run the"
    say "wizard (it remembers your answers), and drop the scope again after setup:"
    note "gh auth refresh -h github.com -s admin:org"
    note "gh auth refresh -h github.com -r admin:org     # afterwards"
    exit 1
  fi
  say "Invited $BOT to $GH_ORG."
  say "Accept the invitation signed in as $BOT (keep using the private window):"
  step "https://github.com/orgs/$GH_ORG/invitation"
  pause "Press Enter once $BOT has accepted"
  state=$(gh api "orgs/$GH_ORG/memberships/$BOT" -q .state 2>/dev/null || echo none)
  [[ "$state" == active ]] || { warn "$BOT's membership is '$state', not active: accept the invitation, then re-run"; exit 1; }
fi
say ""
say "Let members' fine-grained tokens reach the org's repos:"
open_url "https://github.com/organizations/$GH_ORG/settings/personal-access-tokens"
step "Fine-grained tokens: Allow access via fine-grained personal access tokens."
step "Require administrator approval: either works; with it, you approve the bot's"
step "token in stage 6. Classic tokens: Restrict access (the hub doesn't use them)."
pause "Press Enter when saved"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the demo repo"
if gh repo view "$GITHUB_REPO" >/dev/null 2>&1; then
  say "$GITHUB_REPO exists; not touching its contents."
else
  say "Creates $GITHUB_REPO, public, from demo/shop, tagged demo-start."
  confirm "Create and push it?" || exit 1
  cp -r "$REPO/demo/shop" "$WORK/shop"
  ( cd "$WORK/shop"
    git init -q -b main && git add . && git -c commit.gpgsign=false commit -qm "Demo shop"
    git tag demo-start
    gh repo create "$GITHUB_REPO" --public --source . --push >/dev/null
    git push -q origin demo-start )
  say "Created https://github.com/$GITHUB_REPO"
fi
gh api -X PUT "repos/$GITHUB_REPO/collaborators/$BOT" -f permission=push >/dev/null 2>&1 || true
perm=$(gh api "repos/$GITHUB_REPO/collaborators/$BOT/permission" -q .permission 2>/dev/null || echo none)
if [[ "$perm" == write ]]; then check "$BOT has write on $GITHUB_REPO" pass
else check "$BOT has write on $GITHUB_REPO" fail "permission: $perm"; warn "give $BOT Write in the repo's Settings → Collaborators and teams"; pause; fi
[[ "$(gh repo view "$GITHUB_REPO" --json visibility -q .visibility)" == PUBLIC ]] \
  && check "demo repo is public" pass || check "demo repo is public" fail

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Ruleset on main"
say "Pull request with 1 approval, no force push, no deletion, empty bypass list."
if gh api "repos/$GITHUB_REPO/rulesets" -q '.[].name' 2>/dev/null | grep -qx 'main: pull requests only'; then
  say "The ruleset exists."
else
  if gh api -X POST "repos/$GITHUB_REPO/rulesets" --input - >/dev/null 2>"$WORK/err" <<'EOF'
{"name": "main: pull requests only", "target": "branch", "enforcement": "active",
 "conditions": {"ref_name": {"include": ["~DEFAULT_BRANCH"], "exclude": []}},
 "bypass_actors": [],
 "rules": [{"type": "deletion"}, {"type": "non_fast_forward"},
   {"type": "pull_request", "parameters": {"required_approving_review_count": 1,
     "dismiss_stale_reviews_on_push": false, "require_code_owner_review": false,
     "require_last_push_approval": false, "required_review_thread_resolution": false}}]}
EOF
  then
    say "Created through the API."
  else
    warn "the API refused it: $(head -c 300 "$WORK/err")"
    record "Ruleset API call failed: $(head -c 300 "$WORK/err" | tr '\n' ' ')"
    say "Make it by hand instead:"
    open_url "https://github.com/$GITHUB_REPO/settings/rules/new?target=branch"
    step "Name: main: pull requests only. Enforcement: Active. Bypass list: empty."
    step "Target branches: Add target → Include default branch."
    step "Rules: Restrict deletions, Block force pushes, Require a pull request"
    step "before merging with Required approvals: 1. Leave the rest off. Create."
    pause "Press Enter once it's saved"
  fi
fi
rules=$(gh api "repos/$GITHUB_REPO/rules/branches/main" -q '[.[].type] | sort | join(",")' 2>/dev/null || true)
id=$(gh api "repos/$GITHUB_REPO/rulesets" -q '.[] | select(.name == "main: pull requests only") | .id' 2>/dev/null | head -n1)
bypass=$(gh api "repos/$GITHUB_REPO/rulesets/$id" -q '.bypass_actors | length' 2>/dev/null || echo "?")
enf=$(gh api "repos/$GITHUB_REPO/rulesets/$id" -q '.enforcement' 2>/dev/null || echo "?")
approvals=$(gh api "repos/$GITHUB_REPO/rules/branches/main" -q '.[] | select(.type == "pull_request") | .parameters.required_approving_review_count' 2>/dev/null || echo 0)
note "rules on main: $rules · approvals: $approvals · bypass actors: $bypass · $enf"
if [[ "$rules" == *deletion* && "$rules" == *non_fast_forward* && "$rules" == *pull_request* && "$approvals" -ge 1 && "$bypass" == 0 && "$enf" == active ]]; then
  check "ruleset on main: PR + 1 approval, no force push, no deletion, no bypass" pass
else
  check "ruleset on main: PR + 1 approval, no force push, no deletion, no bypass" fail "$rules; approvals $approvals; bypass $bypass; $enf"
  warn "fix the ruleset before the demo"; pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "The from-support label"
if gh label list --repo "$GITHUB_REPO" --json name -q '.[].name' | grep -qx from-support; then
  say "The label exists."
else
  gh label create from-support --repo "$GITHUB_REPO" --color 0e8a16 \
    --description "Opened by the hub from a support report" >/dev/null
  say "Created the from-support label."
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "The hub's token"
say "Signed in as $BOT (private window), create a fine-grained token:"
open_url "https://github.com/settings/personal-access-tokens/new"
step "Name: sandbugs hub. Resource owner: $GH_ORG. Expiration: the day after the event."
step "Repository access: Only select repositories → $DEMO_NAME."
step "Repository permissions: Contents Read and write, Pull requests Read and write."
step "(Metadata Read is added by itself.) Nothing else. Generate token."
step "Save it in the team's password manager, then copy it."
note "If the org requires approval: approve it, as you, at"
note "https://github.com/organizations/$GH_ORG/settings/personal-access-token-requests"
pause "Press Enter when the token is saved (and approved, if needed)"
need_token || exit 1
code=$(tok_api GET "/repos/$GITHUB_REPO")
login=$(tok_api GET /user >/dev/null; jq -r '.login // empty' "$WORK/body")
pulls=$(tok_api GET "/repos/$GITHUB_REPO/pulls")
if [[ "$code" == 200 && "$pulls" == 200 && "${login,,}" == "${BOT,,}" ]]; then
  check "token belongs to $BOT and reads $GITHUB_REPO and its pull requests" pass
else
  check "token works for $GITHUB_REPO" fail "repo $code, pulls $pulls, login '$login'"
  warn "a 404 or 403 usually means the token waits for approval or names the wrong repo"
  exit 1
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Hub repo on the VM"
URL="https://github.com/$GITHUB_REPO.git"
origin=$(vm "sudo -u hub git -C $HUB_REPO remote get-url origin 2>/dev/null || echo none")
if [[ "$origin" == "$URL" ]]; then
  say "$HUB_REPO is already a clone of $URL."
else
  say "$HUB_REPO has origin: $origin. It becomes a clone of $URL."
  say "The old one is kept as $HUB_REPO.pre-spec2. The hub stops until stage 9."
  confirm "Stop the hub, move the old hub repo aside and clone?" || exit 1
  vm "bash -s -- $HUB_REPO $URL" <<'EOF'
set -eu; repo=$1; url=$2
sudo systemctl stop team-workspace-hub
if [ -e "$repo" ] && [ -n "$(sudo ls -A "$repo")" ]; then
  old="$repo.pre-spec2"; [ -e "$old" ] && old="$old.$(date +%s)"
  sudo mv "$repo" "$old"
  echo "  moved the old hub repo to $old"
fi
sudo install -d -o hub -g hub -m 755 "$repo"
sudo -u hub -H git clone -q "$url" "$repo"
echo "  cloned $url"
EOF
fi
origin=$(vm "sudo -u hub git -C $HUB_REPO remote get-url origin 2>/dev/null || echo none")
[[ "$origin" == "$URL" ]] && check "hub repo's origin is $URL (no credentials in it)" pass \
  || check "hub repo's origin is $URL" fail "$origin"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "The VM's .env"
printf '%s\n' "$GITHUB_REPO" | vm_env GITHUB_REPO
printf '%s\n' "$GITHUB_TOKEN" | vm_env GITHUB_TOKEN
runner=$(vm "sudo grep -E '^RUNNER=' $REMOTE_DIR/.env | tail -n1 | cut -d= -f2-")
if [[ "$runner" != real ]]; then
  warn "RUNNER is '$runner'. The check needs real."
  confirm "Set RUNNER=real?" && printf 'real\n' | vm_env RUNNER
fi
hubrepo=$(vm "sudo grep -E '^HUB_REPO_DIR=' $REMOTE_DIR/.env | tail -n1 | cut -d= -f2-")
[[ "$hubrepo" == "$HUB_REPO" ]] || { warn "HUB_REPO_DIR is '$hubrepo'"; printf '%s\n' "$HUB_REPO" | vm_env HUB_REPO_DIR; }
vm "sudo stat -c '%a %U' $REMOTE_DIR/.env" | grep -qx '600 hub' && check ".env is mode 600, owned by hub" pass \
  || check ".env is mode 600, owned by hub" fail

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Deploy main"
say "Runs deploy/update.sh main on the VM (pull, install, build, restart)."
if vm "sudo $REMOTE_DIR/deploy/update.sh main" 2>&1 | tail -n 5 | sed 's/^/  /'; then :; fi
if curl -fsS --max-time 10 "$BASE/api/health" >/dev/null 2>&1; then
  check "hub answers on $BASE/api/health" pass
else
  check "hub answers on /api/health" fail; warn "journalctl -u team-workspace-hub -n 50 on the VM"; exit 1
fi
if vm "sudo journalctl -u team-workspace-hub --since '-5 min' --no-pager" | grep -q "Publishing pull requests to $GITHUB_REPO"; then
  check "hub log: Publishing pull requests to $GITHUB_REPO" pass
else
  check "hub log names $GITHUB_REPO" fail; note "$(vm "sudo journalctl -u team-workspace-hub -n 15 --no-pager" | tail -n 15)"
  pause
fi
record "Deployed main at $(vm "sudo -u hub git -C $REMOTE_DIR rev-parse --short HEAD")"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Forward INC-1042"
since=$(date +%s)
open_url "$BASE/cs"
step "In the support view, open INC-1042 (Discount code says invalid) and forward it."
say "Waiting for the task to end (usually under a minute)…"
TASK=$(wait_task "$since" "$DONE") || { check "INC-1042 task ended" fail "timed out"; exit 1; }
SNAP=$(curl -fsS "$BASE/api/tasks/$TASK")
status=$(jq -r .status <<<"$SNAP")
PR_URL=$(jq -r '.pr.url // empty' <<<"$SNAP")
PR_N=$(jq -r '.pr.number // empty' <<<"$SNAP")
BASE_SHA=$(jq -r '.baseSha // empty' <<<"$SNAP")
BRANCH=$(jq -r .branch <<<"$SNAP")
note "status $status · ${PR_URL:-no PR} · base ${BASE_SHA:0:12} · reason: $(jq -r '.statusReason // "-"' <<<"$SNAP")"
if [[ "$status" == pr_opened && "$PR_URL" == "https://github.com/$GITHUB_REPO/pull/"* ]]; then
  check "INC-1042 ends pr_opened with the PR link in the snapshot" pass "$PR_URL"
else
  check "INC-1042 ends pr_opened" fail "status $status, pr '$PR_URL'"
  warn "a live model run can miss; forward it again by re-running from here, or read the task log in /cs"
  exit 1
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Check the pull request"
gh pr view "$PR_N" --repo "$GITHUB_REPO" --json title,body,labels,files,headRefName,baseRefName,isDraft > "$WORK/pr.json"
say "Title: $(jq -r .title "$WORK/pr.json")"
say "Files changed:"
jq -r '.files[] | "    \(.path)  +\(.additions) -\(.deletions)"' "$WORK/pr.json"
files=$(jq -r '.files[].path' "$WORK/pr.json")
[[ "$(jq -r .headRefName "$WORK/pr.json")" == "$BRANCH" && "$(jq -r .baseRefName "$WORK/pr.json")" == main ]] \
  && check "head $BRANCH, base main" pass || check "head $BRANCH, base main" fail
[[ "$(jq -r .isDraft "$WORK/pr.json")" == false ]] && check "not a draft (green path)" pass || check "not a draft" fail
if grep -qE '(\.test\.|\.spec\.)' <<<"$files" && grep -qvE '(\.test\.|\.spec\.)' <<<"$files" && ! grep -qE '^\.hub/' <<<"$files"; then
  check "files: a reproduction test and a fix, nothing under .hub/" pass "$(tr '\n' ' ' <<<"$files")"
else
  check "files: a reproduction test and a fix, nothing under .hub/" fail "$(tr '\n' ' ' <<<"$files")"
fi
jq -r .body "$WORK/pr.json" | grep -q 'D-014' && check "body cites D-014" pass || check "body cites D-014" fail
jq -r .body "$WORK/pr.json" | grep -q 'Customer report (untrusted, verbatim)' \
  && check "body fences the customer's report" pass || check "body fences the customer's report" fail
jq -r '.labels[].name' "$WORK/pr.json" | grep -qx from-support && check "labelled from-support" pass \
  || check "labelled from-support" fail "a fine-grained token may need Issues: write for labels"
main_sha=$(gh api "repos/$GITHUB_REPO/commits/main" -q .sha)
mb=$(gh api "repos/$GITHUB_REPO/compare/main...$BRANCH" -q .merge_base_commit.sha)
[[ "$BASE_SHA" == "$main_sha" && "$mb" == "$main_sha" ]] \
  && check "baseSha is origin's main and $BRANCH branches from it" pass \
  || check "baseSha is origin's main and $BRANCH branches from it" fail "base $BASE_SHA, main $main_sha, merge base $mb"
say ""
say "Now look at it as a reviewer would:"
open_url "$PR_URL"
step "The receipt renders: header, outcome, files, D-014, the 0 → 1 → 0 test curve."
step "The report sits in a code block under 'Customer report (untrusted, verbatim)'."
step "Files changed holds exactly the reproduction test and the fix."
if confirm "Does it all look right?"; then check "PR reads right to a person" pass
else read -r -p "  What's off? " off || true; check "PR reads right to a person" fail "$off"; fi

# ── 12 ────────────────────────────────────────────────────────────────────
stage "The hub can't merge"
say "Two tries with the hub's token. Both must be refused."
git clone -q "$URL" "$WORK/refuse"
( cd "$WORK/refuse" && git -c user.name=refusal-check -c user.email=refusal@example.invalid \
    -c commit.gpgsign=false commit -q --allow-empty -m "must be refused" )
if out=$(cd "$WORK/refuse" && HUB_PUSH_TOKEN="$GITHUB_TOKEN" GIT_ASKPASS="$ASKPASS" GIT_TERMINAL_PROMPT=0 \
    git -c credential.helper= push origin HEAD:main 2>&1); then
  check "token push to main is refused" fail "IT WENT THROUGH"
  warn "main moved! Revert it with a pull request and fix the ruleset's bypass list."
else
  check "token push to main is refused" pass "$(grep -m1 -iE 'rule|denied|refus|GH0' <<<"$out" | tr -s ' ' | head -c 160)"
fi
code=$(tok_api PUT "/repos/$GITHUB_REPO/pulls/$PR_N/merge" '{}')
if [[ "$code" == 200 ]]; then
  check "token merge of PR #$PR_N is refused" fail "IT MERGED"
  warn "main moved! Revert it with a pull request and fix the ruleset."
else
  check "token merge of PR #$PR_N is refused" pass "HTTP $code: $(jq -r '.message // empty' "$WORK/body" | head -c 120)"
fi

# ── 13 ────────────────────────────────────────────────────────────────────
stage "A merged change reaches the next task"
say "Merge a harmless pull request on GitHub, then forward INC-1042 again:"
say "the new task must start from the new main, with the hub still running."
note "It needs an approval from someone other than its author: $BOT, in the private window."
if confirm "Run this check? (no skips it)"; then
  sync_branch="sync-check-$(date +%s)"
  ( cd "$WORK/refuse" && git reset -q --hard origin/main && git switch -q -c "$sync_branch"
    printf '\nSync check, %s.\n' "$(date -u +%F)" >> README.md
    git -c commit.gpgsign=false commit -qam "README: sync check" && git push -q origin "$sync_branch" )
  sync_url=$(gh pr create --repo "$GITHUB_REPO" --head "$sync_branch" --base main \
    --title "Sync check" --body "Checks that a merged change reaches the hub's next task (#28).")
  say "Opened $sync_url"
  step "As $BOT: Files changed → Review changes → Approve → Submit."
  open_url "$sync_url/files"
  pause "Press Enter once $BOT has approved"
  if gh pr merge "$sync_url" --squash --delete-branch >/dev/null 2>&1; then
    new_main=$(gh api "repos/$GITHUB_REPO/commits/main" -q .sha)
    say "Merged. main is now ${new_main:0:12}."
    since=$(date +%s)
    open_url "$BASE/cs"
    step "Forward INC-1042 again in the support view."
    say "Waiting for the task to end…"
    T2=$(wait_task "$since" "$DONE") || T2=""
    b2=$(curl -fsS "$BASE/api/tasks/$T2" 2>/dev/null | jq -r '.baseSha // empty')
    [[ -n "$T2" && "$b2" == "$new_main" ]] && check "a change merged on GitHub reaches the next task, no restart" pass \
      || check "a change merged on GitHub reaches the next task" fail "task base '$b2', main $new_main"
  else
    check "merge the sync-check PR" fail "gh pr merge refused; was it approved?"
  fi
else
  record "Sync check skipped"
fi

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Reset the demo"
say "Closes the open from-support pull requests and deletes the task/* branches"
say "on GitHub (with the hub's token), then clears the hub's tasks and local"
say "task/* branches on the VM. main stays as it is."
GH_TOKEN="$GITHUB_TOKEN" "$REPO/deploy/reset-demo.sh" "$GITHUB_REPO" --dry-run | sed 's/^/  /'
if confirm "Reset for real?"; then
  if GH_TOKEN="$GITHUB_TOKEN" "$REPO/deploy/reset-demo.sh" "$GITHUB_REPO" | sed 's/^/  /'; then
    vm "cd $HUB_REPO && sudo -u hub git for-each-ref --format='%(refname:short)' refs/heads/task/ | xargs -r sudo -u hub git branch -D >/dev/null; sudo systemctl restart team-workspace-hub"
    open=$(gh api "repos/$GITHUB_REPO/pulls?state=open" -q '[.[] | select(any(.labels[]; .name == "from-support"))] | length')
    left=$(gh api "repos/$GITHUB_REPO/branches?per_page=100" -q '[.[].name | select(startswith("task/"))] | length')
    [[ "$open" == 0 && "$left" == 0 ]] && check "reset script leaves no from-support PRs or task/* branches" pass \
      || check "reset script cleans up" fail "$open open PRs, $left task/* branches"
  else
    check "reset script runs with the token" fail
  fi
else
  record "Reset skipped"
fi
GITHUB_TOKEN=""

finish
say "Run record: $FINDINGS"
if confirm "Post the record as a comment on #28?"; then
  body=$(awk '/^## Demo repo run/{buf=""} {buf=buf $0 "\n"} END{printf "%s", buf}' "$FINDINGS")
  printf '%s\n\nPosted by deploy/demo-repo-wizard.sh.\n' "$body" \
    | gh issue comment 28 --repo "$(cd "$REPO" && gh repo view --json nameWithOwner -q .nameWithOwner)" --body-file - >/dev/null \
    && say "Posted." || warn "couldn't post; it's in $FINDINGS"
fi
